/** Removes exactly the captured provider messages belonging to a deleted subject. */
export async function deleteMailpitMessages(ids: string[]): Promise<void> {
  if (ids.length === 0) return;
  const response = await request('/api/v1/messages', {
    method: 'DELETE',
    headers: { 'content-type': 'application/json' },
    body: JSON.stringify({ IDs: ids }),
  });
  if (!response.ok) throw new Error(`mailpit_delete_failed:${response.status}`);
}

export async function deleteMailpitMessagesForRecipient(destination: string): Promise<void> {
  await deleteMailpitMessages(await matchingMessageIds(destination));
}

